/* ============================================================================
   PT SUPRACOR SEJAHTERA — PERBARUI PATOKAN DARI EXCEL 13 AGUSTUS
   Dibuat : 14 Agustus 2026

   PERBANDINGAN YANG DIMINTA

     Excel  : terisi lengkap sampai 12 Agustus (kolom 13 Agustus baru berisi
              retur kecil, STB dan DLV-nya masih nol)
     Web    : posisi 14 Agustus

                        Excel 12 Agu     Web 14 Agu      Selisih
        BOX                 764.819        650.207       -114.612
        PART+LAYER          187.294        261.898        +74.604
        SHEET                     -          4.064         +4.064
        TOTAL               952.113        916.169        -35.944

   PENYEBAB UTAMA — SALDO AWAL PART+LAYER SUDAH DIREVISI GUDANG

        Patokan di database   256.771 pc   81 NO. OP
        Excel sekarang        184.785 pc   39 NO. OP
        Selisih               -71.986 pc

     Gudang merevisi saldo awal Agustus untuk sheet PART+LAYER, tapi patokan
     di database masih memakai angka lama yang dipasang 10 Agustus. Karena itu
     PART+LAYER di web kelebihan sekitar 72 ribu pc.

     Saldo awal BOX tidak berubah, tetap 777.727 pc.

   PENYEBAB LAIN, YANG MEMANG WAJAR

     1. Beda tanggal posisi. Excel berhenti di 12 Agustus, web sudah 14 Agustus.
        Dua hari mutasi belum tercermin di Excel.
     2. Barang SHEET 4.064 pc hanya ada di web. Lembaran memang tidak dicatat
        di file gudang.
     3. Stok minus di web naik jadi 106 NO. OP. Ini akibat patokan 31 Juli yang
        makin jauh, dan sebagian besar sudah dipetakan sebabnya pada 10 Agustus.

   FILE INI MENGGANTI PATOKAN DENGAN SALDO AWAL VERSI TERBARU.
   Patokan lama diarsipkan lebih dulu.
   ============================================================================ */

USE dbSopanusa;
GO
SET NOCOUNT ON;
GO

/* ---------------------------------------------------------------------------
   LANGKAH 1 — ARSIPKAN PATOKAN YANG BERLAKU SEKARANG
   --------------------------------------------------------------------------- */
IF OBJECT_ID('dbo.tbStokGudangExcel_BAK_1408') IS NULL
    SELECT * INTO dbo.tbStokGudangExcel_BAK_1408 FROM dbo.tbStokGudangExcel;
GO
SELECT cKategori, COUNT(*) AS baris, SUM(nStokAkhirPc) AS pc
FROM   dbo.tbStokGudangExcel_BAK_1408 GROUP BY cKategori;
GO

/* ---------------------------------------------------------------------------
   LANGKAH 2 — ISI PATOKAN BARU, TETAP CUT-OFF 31 JULI 2026
   Yang dipakai kolom SALDO AWAL, bukan saldo akhir, supaya seluruh mutasi
   Agustus tetap diambil dari database.
   --------------------------------------------------------------------------- */
DELETE FROM dbo.tbStokGudangExcel;
GO

GO

GO

GO

GO

GO

GO

GO

UPDATE dbo.tbStokGudangExcel
SET    cNoScDb = 'SLC/' + LEFT(RTRIM(cNoOpExcel), CHARINDEX('-', RTRIM(cNoOpExcel) + '-') - 1)
WHERE  CHARINDEX('-', cNoOpExcel) > 0;

UPDATE e SET e.cNoScDb = NULL FROM dbo.tbStokGudangExcel e
WHERE  NOT EXISTS (SELECT 1 FROM dbo.tbStbBJ b WHERE RTRIM(b.cNoSc) = e.cNoScDb);
GO

-- Target: BOX 777.727 pc, PART+LAYER 184.785 pc, belum_ketemu 0
SELECT cKategori, COUNT(*) AS baris,
       SUM(CASE WHEN cNoScDb IS NULL THEN 1 ELSE 0 END) AS belum_ketemu,
       SUM(nStokAkhirPc) AS total_pc
FROM   dbo.tbStokGudangExcel GROUP BY cKategori;

SELECT cNoOpExcel, cKategori, cNama, nStokAkhirPc
FROM   dbo.tbStokGudangExcel WHERE cNoScDb IS NULL ORDER BY nStokAkhirPc DESC;
GO

/* ---------------------------------------------------------------------------
   LANGKAH 3 — HITUNG ULANG
   --------------------------------------------------------------------------- */
EXEC dbo.spRefreshSemuaStok @Sumber = 'PATOKAN13AGU';
GO

SELECT cKelompok, COUNT(*) AS jml_sc, SUM(nStokPc) AS total_pc, SUM(nStokKg) AS total_kg
FROM   dbo.tbStokSnapTipe GROUP BY cKelompok ORDER BY SUM(nStokPc) DESC;

SELECT cStatusData, COUNT(*) AS jml_op, SUM(nStokPc) AS total_pc
FROM   dbo.tbStokGudangSnap GROUP BY cStatusData ORDER BY jml_op DESC;
GO

/* ---------------------------------------------------------------------------
   LANGKAH 4 — BANDINGKAN PADA POSISI YANG SAMA, 12 AGUSTUS
   Ini perbandingan yang setara. Excel berhenti di 12 Agustus, jadi stok
   sistem juga dihitung pada tanggal itu.
   --------------------------------------------------------------------------- */
EXEC dbo.spStokPerTanggal '2026-08-12';
GO

-- Sasaran: BOX 764.819 pc, PART+LAYER 187.294 pc
-- Angka di bawah masih gabungan semua tipe, karena spStokPerTanggal tidak
-- memecah per kelompok. Untuk rincian per tipe pakai spRefreshStokTipe.
EXEC dbo.spRefreshStokTipe '2026-08-12';
GO

SELECT k.kategori, k.excel_12agu, ISNULL(y.pc,0) AS sistem_12agu,
       ISNULL(y.pc,0) - k.excel_12agu AS selisih,
       CAST(100.0 * (1 - ABS(ISNULL(y.pc,0) - k.excel_12agu)
            / NULLIF(CAST(k.excel_12agu AS DECIMAL(18,2)),0)) AS DECIMAL(5,2)) AS akurasi_persen
FROM   (SELECT 'BOX' AS kategori, 764819 AS excel_12agu
        UNION ALL SELECT 'PART+LAYER', 187294) k
LEFT JOIN (SELECT cKelompok AS kategori, SUM(nStokPc) AS pc
           FROM dbo.tbStokSnapTipe GROUP BY cKelompok) y ON y.kategori = k.kategori;
GO

/* ---------------------------------------------------------------------------
   LANGKAH 5 — KEMBALIKAN SNAPSHOT KE POSISI HARI INI
   Langkah 4 menyetel snapshot ke 12 Agustus. Wajib dikembalikan supaya
   dashboard menampilkan posisi terkini lagi.
   --------------------------------------------------------------------------- */
EXEC dbo.spRefreshSemuaStok @Sumber = 'KEMBALI';
GO

SELECT cKelompok, COUNT(*) AS jml_sc, SUM(nStokPc) AS total_pc, MAX(dPosisi) AS posisi
FROM   dbo.tbStokSnapTipe GROUP BY cKelompok;
GO
